WITH base AS (SELECT * FROM inventory WHERE store_id IN (1, 3) AND quantity < 239), inventory_stats AS (SELECT CASE WHEN quantity >= 260 THEN 'high' WHEN quantity >= 68 THEN 'mid' ELSE 'low' END AS quantity_bucket, SUM(quantity) AS total_quantity, MAX(quantity) - MIN(quantity) AS quantity_range FROM base GROUP BY CASE WHEN quantity >= 260 THEN 'high' WHEN quantity >= 68 THEN 'mid' ELSE 'low' END) SELECT quantity_bucket, total_quantity, quantity_range FROM inventory_stats;
